initialize:
const ModbusRTU = global.get('modbusSerial');

if (!ModbusRTU) {
    node.error('Modulo modbus-serial nao encontrado em functionGlobalContext. Veja node-red/README.md.');
    return;
}

/*
=====================================
AJUSTE 1: dados de rede do CLP
=====================================
*/
const clpConfig = {
    ip: '10.200.7.254',   // <-- IP do CLP na rede local
    port: 502,            // porta Modbus TCP (502 e o padrao)
    unitId: 1,             // endereco/estacao do CLP (slave id)
};

/*
=====================================
AJUSTE 2: mapa de memoria do CLP
=====================================

Endereços 0-based. Ajuste conforme o
programa ladder/estruturado do seu CLP.
Esses nomes sao usados pelos outros
nodes desta flow, nao precisa mexer
em mais nada alem deste mapa.
*/
const clpRegs = {
    coils: {
        // %M10/%M11/%M12 adicionados em paralelo com %M1/%M2/%M3
        // nos Rung0/1/2 do programa do CLP (EcoStruxure Machine Expert Basic).
        // Regra de enderecamento confirmada empiricamente (forcar %M10 e
        // escanear Modbus): %Mn = endereco Modbus n, direto, sem deslocamento.
        jogCima: 10,      // %M10 - em paralelo com %M1 (Rung0 -> Q0.0 sobe)
        jogBaixo: 11,     // %M11 - em paralelo com %M2 (Rung1 -> Q0.1 desce)
        mesaStart: 12,    // %M12 - em paralelo com %M3 (Rung2 -> Q0.2 mesa)
        soldaOn: 3,       // AINDA NAO LIGADO NO CLP (sem rung para Q0.3/LED)
        emergencia: 4,    // NAO USAR - emergencia e uma ENTRADA (I0.4), nao existe coil pra isso
    },
    holdingRegisters: {
        zAlvoDecimm: 0,        // posicao Z alvo, em decimos de mm (inteiro)
        mesaAlvoDecigraus: 1,  // angulo alvo da mesa, em decimos de grau
    },
    inputRegisters: {
        zAtualDecimm: 0,       // posicao Z real, em decimos de mm
        mesaAtualDecigraus: 1, // angulo real da mesa, em decimos de grau
    },
    discreteInputs: {
        // lidos em sequencia a partir do endereco 'executando' (5 bits)
        executando: 0,
        mesaPronta: 1,
        soldaAtiva: 2,
        emergenciaAtiva: 3,
        movimentoConcluido: 4,
    },
};

global.set('clpConfig', clpConfig);
global.set('clpRegs', clpRegs);
global.set('clpEstado', { conectado: false, ultimaTentativa: 0 });

const client = new ModbusRTU();
client.setTimeout(2000);
global.set('clpClient', client);

function conectar() {
    client.connectTCP(clpConfig.ip, { port: clpConfig.port })
        .then(async () => {
            client.setID(clpConfig.unitId);

            /*
            Estado seguro ao conectar: os bits remotos
            (%M10/%M11/%M12) podem ter ficado LIGADOS de uma
            sessao anterior (ex.: navegador fechado com a mesa
            girando) - o CLP mantem o ultimo valor escrito
            independente do Node-RED estar rodando ou nao.
            Zera tudo ao conectar, para nunca herdar um estado
            perigoso.
            */
            try {
                await client.writeCoil(clpRegs.coils.jogCima, false);
                await client.writeCoil(clpRegs.coils.jogBaixo, false);
                await client.writeCoil(clpRegs.coils.mesaStart, false);
                node.log('Estado remoto zerado ao conectar (jogCima/jogBaixo/mesaStart = OFF).');
            } catch (erroReset) {
                node.warn('Nao foi possivel zerar o estado remoto ao conectar: ' + erroReset.message);
            }

            global.set('clpEstado', { conectado: true, ultimaTentativa: Date.now() });
            node.log('Conectado ao CLP via Modbus TCP em ' + clpConfig.ip + ':' + clpConfig.port);
        })
        .catch((erro) => {
            global.set('clpEstado', { conectado: false, ultimaTentativa: Date.now() });
            node.warn('Falha ao conectar ao CLP (' + clpConfig.ip + '): ' + erro.message + ' - nova tentativa em 3s.');
            setTimeout(conectar, 3000);
        });
}

client.on('close', () => {
    global.set('clpEstado', { conectado: false, ultimaTentativa: Date.now() });
    node.warn('Conexao Modbus com o CLP caiu. Tentando reconectar...');
    setTimeout(conectar, 3000);
});

conectar();

finalize:
const client = global.get('clpClient');
if (client) {
    try { client.close(() => {}); } catch (erro) { /* ignorar */ }
}

func:
const client = global.get('clpClient');
const regs = global.get('clpRegs');
const estado = global.get('clpEstado');
const corpo = msg.payload || {};
const idComando = corpo.idComando || null;
const comando = String(corpo.comando || '').toUpperCase();
const dados = corpo.dados || {};

function respostaOk(extra) {
    return {
        topic: 'soldatech/maquina/resposta',
        payload: Object.assign({ idComando, tipo: 'COMANDO_OK', comando, timestamp: Date.now() }, extra || {}),
    };
}

function respostaErro(mensagem, codigo) {
    return {
        topic: 'soldatech/maquina/erro',
        payload: { idComando, tipo: 'COMANDO_ERRO', comando, mensagem, codigo: codigo || 'ERRO_CLP', timestamp: Date.now() },
    };
}

// PING nao depende do CLP: serve so para testar a ponte MQTT/Node-RED.
if (comando === 'PING') {
    node.send([respostaOk({ mensagem: 'pong' }), null]);
    return;
}

if (!regs || !client) {
    node.send([null, respostaErro('Node-RED ainda nao terminou de inicializar a conexao com o CLP.', 'CLP_NAO_INICIALIZADO')]);
    return;
}

if (!estado || !estado.conectado) {
    node.send([null, respostaErro('Node-RED sem conexao Modbus com o CLP no momento.', 'CLP_OFFLINE')]);
    return;
}

(async () => {
    try {
        switch (comando) {
            case 'JOG_CIMA':
                await client.writeCoil(regs.coils.jogBaixo, false);
                await client.writeCoil(regs.coils.jogCima, true);
                break;

            case 'JOG_BAIXO':
                await client.writeCoil(regs.coils.jogCima, false);
                await client.writeCoil(regs.coils.jogBaixo, true);
                break;

            case 'JOG_PULSO': {
                // Pulso com duracao EXATA controlada aqui (nao pelo
                // tempo de clique no navegador) - usado para calibrar
                // o deslocamento minimo por toque.
                const direcaoPulso = String(dados.direcao || '').toUpperCase();
                const duracaoMs = Math.max(5, Math.min(2000, Number(dados.duracaoMs) || 30));
                const coilPulso = direcaoPulso === 'CIMA' ? regs.coils.jogCima : regs.coils.jogBaixo;

                if (direcaoPulso !== 'CIMA' && direcaoPulso !== 'BAIXO') {
                    throw new Error('JOG_PULSO precisa de dados.direcao CIMA ou BAIXO, recebido: ' + direcaoPulso);
                }

                await client.writeCoil(coilPulso, true);
                await new Promise((resolve) => setTimeout(resolve, duracaoMs));
                await client.writeCoil(coilPulso, false);
                break;
            }

            case 'JOG_PARAR':
                await client.writeCoil(regs.coils.jogCima, false);
                await client.writeCoil(regs.coils.jogBaixo, false);
                break;

            case 'MESA_START':
                await client.writeCoil(regs.coils.mesaStart, true);
                break;

            case 'MESA_STOP':
                await client.writeCoil(regs.coils.mesaStart, false);
                break;

            case 'SOLDA_ON':
                await client.writeCoil(regs.coils.soldaOn, true);
                break;

            case 'SOLDA_OFF':
                await client.writeCoil(regs.coils.soldaOn, false);
                break;

            case 'MOVER_PONTO': {
                const zMm = Number(dados.zMm);

                if (!Number.isFinite(zMm)) {
                    throw new Error('Ponto sem zMm valido: ' + JSON.stringify(dados));
                }

                flow.set('idComandoMovimentoPendente', idComando);
                await client.writeRegister(regs.holdingRegisters.zAlvoDecimm, Math.round(zMm * 10));


                if (dados.anguloMesaGraus !== undefined) {
                    node.warn('MOVER_PONTO pediu anguloMesaGraus=' + dados.anguloMesaGraus + ', mas o giro automatico da mesa para um angulo especifico ainda nao esta calibrado/habilitado (falta medir graus por segundo reais e a mesa so gira em 1 sentido no CLP hoje). Nada foi acionado na mesa.');
                }
                break;
            }

            case 'EMERGENCIA':
                await client.writeCoil(regs.coils.emergencia, true);
                break;

            default:
                node.send([null, respostaErro('Comando nao reconhecido pela ponte Node-RED: ' + comando, 'COMANDO_INVALIDO')]);
                return;
        }

        // MOVER_PONTO so confirma via PONTO_ATINGIDO, publicado pelo loop de
        // status quando o CLP sinalizar 'movimentoConcluido' (ver node de status).
        if (comando !== 'MOVER_PONTO') {
            node.send([respostaOk(), null]);
        }
    } catch (erro) {
        node.send([null, respostaErro(erro.message, 'ERRO_MODBUS')]);
    }
})();

return null;

const client = global.get('clpClient');
const regs = global.get('clpRegs');
const estado = global.get('clpEstado');

if (!client || !regs || !estado || !estado.conectado) {
    // Sem CLP conectado ainda: nao publica um STATUS inventado.
    return null;
}

(async () => {
    try {
        // Encoder do eixo Z e da mesa ainda NAO estao cabeados (ver
        // I0.0/I0.1 'em breve'). Enquanto isso, NAO publicamos
        // posicaoZMm/anguloMesaGraus - se publicassemos um valor fixo
        // (ex.: 0), isso atrapalharia a animacao visual do navegador,
        // que faz uma estimativa por enquanto. Reativar as duas linhas
        // de leitura de inputRegisters e os dois campos abaixo assim
        // que o encoder estiver cabeado e o mapa de enderecos dele
        // confirmado (mesma tecnica: forcar e escanear Modbus).
        const discretos = await client.readDiscreteInputs(regs.discreteInputs.executando, 5);

        const bits = discretos.data;
        const executando = Boolean(bits[0]);
        const mesaPronta = Boolean(bits[1]);
        const soldaAtiva = Boolean(bits[2]);
        const emergenciaAtiva = Boolean(bits[3]);
        const movimentoConcluido = Boolean(bits[4]);

        const statusMsg = {
            topic: 'soldatech/maquina/status',
            payload: {
                tipo: 'STATUS',
                estado: emergenciaAtiva ? 'EMERGENCIA' : (executando ? 'EXECUTANDO' : 'PARADA'),
                mesaPronta,
                soldaAtiva,
                emergencia: emergenciaAtiva,
                timestamp: Date.now(),
            },
        };

        let mesaReadyMsg = null;
        let pontoAtingidoMsg = null;

        const mesaProntaAnterior = flow.get('mesaProntaAnterior') || false;
        if (mesaPronta && !mesaProntaAnterior) {
            mesaReadyMsg = { topic: 'soldatech/maquina/resposta', payload: { tipo: 'MESA_READY', timestamp: Date.now() } };
        }
        flow.set('mesaProntaAnterior', mesaPronta);

        const movimentoConcluidoAnterior = flow.get('movimentoConcluidoAnterior') || false;
        if (movimentoConcluido && !movimentoConcluidoAnterior) {
            const idComandoMovimento = flow.get('idComandoMovimentoPendente') || null;
            pontoAtingidoMsg = {
                topic: 'soldatech/maquina/resposta',
                payload: { idComando: idComandoMovimento, tipo: 'PONTO_ATINGIDO', timestamp: Date.now() },
            };
        }
        flow.set('movimentoConcluidoAnterior', movimentoConcluido);

        node.send([statusMsg, mesaReadyMsg, pontoAtingidoMsg]);
    } catch (erro) {
        node.warn('Erro ao ler status do CLP: ' + erro.message);
    }
})();

return null;
